{
  "name": "高密度任意波形发生器",
  "name_en": "HDAWG High-Density Arbitrary Waveform Generator",
  "manufacturer": "Zurich Instruments",
  "description": "这是一种高性能任意波形发生器，用于输出精确定时的可编程模拟波形，并支持序列控制、波形存储和命令表配置。它常用于量子控制实验、脉冲序列生成以及与PQSC等系统同步的QCCS实验平台。",
  "description_en": "This is a high-performance arbitrary waveform generator used to produce precisely timed programmable analog waveforms, with support for sequencing, waveform memory, and command-table-based control. It is commonly used in quantum control experiments, pulse sequence generation, and synchronized operation within QCCS setups together with instruments such as the PQSC.",
  "tag_hints": [
    "arbitrary waveform generation",
    "quantum control",
    "QCCS synchronization",
    "sequencer programming",
    "waveform memory",
    "command table"
  ],
  "actions": [
    {
      "action_name": "auto-enable_qccs_mode",
      "description": "将仪器配置为QCCS模式，以便与PQSC同步工作。",
      "description_en": "Configure the instrument for QCCS mode so it can operate in sync with a PQSC."
    },
    {
      "action_name": "auto-check_status",
      "description": "检查命令表状态。",
      "description_en": "Check the status of the command table."
    },
    {
      "action_name": "auto-load_validation_schema",
      "description": "获取命令表的验证架构。",
      "description_en": "Load the validation schema for the command table."
    },
    {
      "action_name": "auto-upload_to_device",
      "description": "将命令表上传到仪器。",
      "description_en": "Upload the command table to the instrument."
    },
    {
      "action_name": "auto-load_from_device",
      "description": "从仪器读取命令表。",
      "description_en": "Load the command table from the instrument."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用AWG序列器。",
      "description_en": "Enable the AWG sequencer."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待序列器执行完成。",
      "description_en": "Wait until the sequencer has finished running."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译AWG序列程序。",
      "description_en": "Compile the AWG sequencer program."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将序列程序加载到AWG。",
      "description_en": "Load a sequencer program into the AWG."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "将波形写入仪器的波形存储器。",
      "description_en": "Write waveforms to the instrument's waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从仪器的波形存储器读取波形。",
      "description_en": "Read waveforms from the instrument's waveform memory."
    }
  ]
}

